function tags(v:string[]|string){return Array.isArray(v)?v:v.split(/[·,，]/).map(x=>x.trim()).filter(Boolean)}
onMounted(async()=>{try{const d=(await api.get<Record<string,any>>('/api/site/profile')).data;if(d&&Object.keys(d).length)profile.value={...profile.value,...d,note_paragraphs:Array.isArray(d.note_paragraphs)?d.note_paragraphs:profile.value.note_paragraphs,directions:Array.isArray(d.directions)?d.directions:profile.value.directions}}catch{/* fallback to built-in content */}})
</script>
